#include <bits/stdc++.h>

using namespace std;

#define inf (long long)1e15
#define ll long long
#define all(x) x.begin(), x.end()
#define x first
#define y second

const int N = 200010;
const int MAX_VAL = 1000010;

vector<ll> sequence({0ll});
int min_steps = MAX_VAL;

void recurse(ll x, int steps) {
    if (steps > min_steps)
        return;
    if (x == 0) {
        min_steps = steps;
        return;
    }
    auto lower_it = lower_bound(all(sequence), x);
    auto upper_it = upper_bound(all(sequence), x);
    if (lower_it == upper_it) lower_it--;
    ll diff1 = x - *lower_it;
    int cost = lower_it - sequence.begin();
    ll diff2 = *upper_it - x;
    recurse(x % *lower_it, steps + cost * (x / *lower_it));
    recurse(diff2, steps + cost + 1);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    ll n;
    cin >> n;
    for (int i = 1; i <= 16; ++i) {
        sequence.push_back(sequence.back() * 10 + 1);
    }
    recurse(n, 0);
    cout << min_steps << "\n";
    return 0;
}
